for scenario in ['same-before','same-after']:
 names=[f'observed-generic_in_double_zero_single-{scenario}-normal-12-initial',f'observed-generic_in_double_zero_single-{scenario}-normal-36-extension']
 pairs=[]
 for name in names:
  r=load(p/name/'runs.json')
  for pair in range(r['pair_count']):
   x={run['label']:run for run in r['runs'] if run['pair']==pair}
   pairs.append({'directory':name,'pair':pair,'change_pct':100*(x['after']['median_ms']/x['before']['median_ms']-1)})
 assert len(pairs)==48
 ratios=[r['change_pct'] for r in pairs];rng=random.Random(88);boot=sorted(statistics.median(rng.choices(ratios,k=48)) for _ in range(10000));lo,hi=boot[249],boot[9749]
 result[scenario]={'pairs':48,'median_paired_change_pct':statistics.median(ratios),'paired_median_bootstrap_95_percentile_interval':[lo,hi],'precision_target_met':-1<=lo<=hi<=1,'source_pairs':pairs}
