import json,random,statistics
from pathlib import Path
p=Path(__file__).parent
load=lambda f:json.loads(Path(f).read_text())
cases=load(p/'measurement-plan.json')['execution_extension']['cases'];result={}
for case in cases:
 names=[f'observed-{case}-paired-normal-16-initial',f'observed-{case}-paired-normal-32-precision']
 pairs=[]
 for name in names:
  r=load(p/name/'runs.json')
  for pair in range(r['pair_count']):
   x={run['label']:run for run in r['runs'] if run['pair']==pair}
   counter=lambda v:float(next(c['counter-value'] for c in x[v]['counters'] if c['event']=='instructions:u'))
   pairs.append({'directory':name,'pair':pair,'median_change_pct':100*(x['after']['median_ms']/x['before']['median_ms']-1),'mean_change_pct':100*(statistics.mean(x['after']['samples_ms'])/statistics.mean(x['before']['samples_ms'])-1),'instruction_change_pct':100*(counter('after')/counter('before')-1)})
 assert len(pairs)==48
 row={'pairs':48,'source_pairs':pairs}
 for metric in ['median','mean']:
  values=[r[f'{metric}_change_pct'] for r in pairs];rng=random.Random(88);boot=sorted(statistics.median(rng.choices(values,k=48)) for _ in range(10000))
  row[metric]={'median_paired_change_pct':statistics.median(values),'paired_median_bootstrap_95_percentile_interval':[boot[249],boot[9749]]}
 row['median_paired_instruction_change_pct']=statistics.median(r['instruction_change_pct'] for r in pairs)
 result[case]=row
 print(case,{k:v for k,v in row.items() if k!='source_pairs'},flush=True)
(p/'combined-execution.json').write_text(json.dumps(result,indent=2)+'\n')

